"""Abelian fields generated by a short Gaussian period, Q(\\zeta_f^{h_1} + ... + \\zeta_f^{h_k}),
computed with PARI (via cypari2).

By Kronecker-Weber every abelian field K lies in some Q(\\zeta_f), and then K = Q(\\zeta_f)^H is
the fixed field of a subgroup H of (Z/fZ)^*. The Gaussian period

    eta = sum_{h in H} \\zeta_f^h

lies in K, and often generates it, e.g. 3.3.169.1 = \\Q(\\zeta_{13} + \\zeta_{13}^{5} + \\zeta_{13}^{8} + \\zeta_{13}^{12})
with H = <5> = {1, 5, 8, 12} in (Z/13Z)^*. The name has one term per element of H, so we only
use it when |H| <= MAX_TERMS (5), i.e. for [Q(\\zeta_f) : K] <= 5.

Conventions:

  * f is not 2 mod 4 (as for cyclotomic fields), and the exponents are the elements of H, in
    increasing order (so the first term is \\zeta_f itself);
  * f is the conductor of K, so that (f, H) is determined by K, and has the fewest terms: H
    does not contain the kernel of (Z/fZ)^* -> (Z/(f/p)Z)^* for any prime p dividing f
    (otherwise K lies in Q(\\zeta_{f/p}));
  * |H| >= 2, and H is not {1, -1} (those are the cyclotomic fields Q(\\zeta_f) and the real
    cyclotomic fields Q(\\zeta_f)^+, which have their own names);
  * eta must generate K (for some H it generates a smaller field, and those K get no name).

As |H| <= 5, phi(f) <= 5 [K : Q], so each degree has only finitely many of these fields, and the
list of them for a degree (periods) is complete. Other families' names win over these (e.g.
\\Q(\\zeta_{5}, \\sqrt{2}) and \\Q(\\sqrt{5 + 2\\sqrt{5}})), except the families that come after it
in FAMILIES (nested biquadratic, nested pure, nested quartic and Cardano cubics).
"""

import math
from dataclasses import dataclass

from nf_names import period_key
from pari_fields import make_field, pari

from cypari2.handle_error import PariError  # (after pari_fields, which checks cypari2 is there)

MAX_TERMS = 5


def period_name(f, H):
    terms = [r"\zeta_{%d}" % f if h == 1 else r"\zeta_{%d}^{%d}" % (f, h) for h in sorted(H)]
    return r"\Q(%s)" % " + ".join(terms)


def simplicity(f, H):
    return period_key(f, H)


def _totients(bound):
    phi = list(range(bound + 1))
    for p in range(2, bound + 1):
        if phi[p] == p:  # p is prime
            for m in range(p, bound + 1, p):
                phi[m] -= phi[m] // p
    return phi


def conductors(n, max_terms=MAX_TERMS):
    """The f, not 2 mod 4, with phi(f) = n k for some 2 <= k <= max_terms."""
    max_phi = n * max_terms
    bound = 2 * max_phi ** 2  # phi(f) >= sqrt(f/2)
    phi = _totients(bound)
    return [f for f in range(3, bound + 1)
            if f % 4 != 2 and phi[f] % n == 0 and 2 <= phi[f] // n <= max_terms]


def small_subgroups(f, order):
    """The subgroups of (Z/fZ)^* of the given order (at most 5), as sorted tuples."""
    units = [a for a in range(1, f) if math.gcd(a, f) == 1]
    out = set()
    for a in units:
        H = _cyclic(a, f)
        if len(H) == order:
            out.add(H)
    if order == 4:  # also the Klein four-groups {1, a, b, ab}
        invs = [a for a in units if a != 1 and a * a % f == 1]
        for i, a in enumerate(invs):
            for b in invs[i + 1:]:
                out.add(tuple(sorted({1, a, b, a * b % f})))
    return sorted(out)


def _cyclic(a, f):
    H, x = [1], a % f
    while x != 1:
        H.append(x)
        x = x * a % f
    return tuple(sorted(H))


# prod over the conjugates eta_c (c over coset representatives of H) of x - eta_c, rounded.
# round also gives the binary exponent of the rounding error, e.
_CONJ_PRODUCT = pari("""(f, H, cs, bits) -> localbitprec(bits);
    my(z = exp(2 * Pi * I / f), P, e);
    P = prod(i = 1, #cs, 'x - sum(j = 1, #H, z^(cs[i] * H[j] % f)));
    P = round(real(P), &e);
    [P, e]""")


def period_poly(f, H):
    """The minimal polynomial of eta = sum_{h in H} \\zeta_f^h (in x), or None if eta does not
    generate Q(\\zeta_f)^H."""
    Hs = set(H)
    cs, seen = [], set()
    for a in range(1, f):
        if math.gcd(a, f) == 1 and a not in seen:
            cs.append(a)
            seen.update(a * h % f for h in Hs)
    # Its coefficients are at most (|H| + 1)^n in absolute value.
    bits = 64 + int(len(cs) * math.log2(len(H) + 1))
    while True:
        P, e = _CONJ_PRODUCT(f, list(H), cs, bits)
        if e < -16:
            break
        bits *= 2
    eta = pari(" + ".join(f"x^{h}" for h in H))
    if pari.substpol(P, pari("x"), pari.Mod(eta, pari.polcyclo(f))) != 0:
        raise ArithmeticError(f"rounding failed for f = {f}, H = {H}")
    return P if pari.issquarefree(P) else None


def is_valid(f, H):
    return len(H) >= 2 and H != (1, f - 1) and is_conductor(f, H)


def is_conductor(f, H):
    """Whether f is the conductor of Q(\\zeta_f)^H: H contains no kernel of reduction mod f/p."""
    Hs = set(H)
    for p in {int(p) for p in pari.factor(f)[0]}:
        g = f // p
        kernel = [a for a in range(1, f, g) if math.gcd(a, f) == 1]  # a = 1 mod f/p
        if all(a in Hs for a in kernel):
            return False
    return True


@dataclass(frozen=True)
class Period:
    f: int
    H: tuple
    poly: object     # minimal polynomial of eta (a PARI polynomial in x)
    disc_abs: int    # |disc K|
    r1: int          # K is totally real (r1 = n) if -1 is in H, otherwise totally complex

    @property
    def name(self):
        return period_name(self.f, self.H)


_PERIODS = {}


def periods(n, max_terms=MAX_TERMS, progress=None):
    """The Periods of the fields of degree n named by a Gaussian period with at most max_terms
    terms. Each field appears once, as (f, H) is determined by K. Computed once per
    (n, max_terms).

    If given, progress(done, total, extra) is called after each f.
    """
    key = (n, max_terms)
    if key in _PERIODS:
        return _PERIODS[key]
    out = []
    fs = conductors(n, max_terms)
    for i, f in enumerate(fs, start=1):
        k = int(pari.eulerphi(f)) // n
        primes = [int(p) for p in pari.factor(f)[0]]
        for H in small_subgroups(f, k):
            if not is_valid(f, H):
                continue
            g = period_poly(f, H)
            if g is None:  # eta generates a smaller field
                continue
            # K is only ramified at primes dividing f, which makes nfdisc fast
            disc_abs = abs(int(pari.nfdisc([g, primes])))
            out.append(Period(f, H, g, disc_abs, n if f - 1 in H else 0))
        if progress:
            progress(i, len(fs), f", {len(out)} fields so far")
    _PERIODS[key] = out
    return out


def period_fields(degrees, max_terms=MAX_TERMS, progress=None):
    """The fields of the given degrees (each >= 3) named by a Gaussian period with at most
    max_terms terms, as Fields (with polredabs polynomials, or polredbest ones where polredabs
    runs out of PARI stack).

    If given, progress(done, total, extra) is called after each degree.
    """
    out = []
    for i, n in enumerate(degrees, start=1):
        for P in periods(n, max_terms):
            primes = [int(p) for p in pari.factor(P.f)[0]]
            try:
                g = pari.polredabs([P.poly, primes])
            except PariError:  # stack overflow in large degree: the LMFDB lookup also
                g = pari.polredbest([P.poly, primes])  # matches by isomorphism
            out.append(make_field(P.name, tuple(int(c) for c in pari.Vecrev(g))))
        if progress:
            progress(i, len(degrees), f", {len(out)} fields so far")
    return out
